def maxGuests(favorite):
    n = len(favorite)
    indeg = [0] * n
    for f in favorite:
        indeg[f] += 1
    depth = [1] * n
    queue = [i for i in range(n) if indeg[i] == 0]
    removed = [False] * n
    while queue:
        u = queue.pop()
        removed[u] = True
        v = favorite[u]
        if depth[u] + 1 > depth[v]:
            depth[v] = depth[u] + 1
        indeg[v] -= 1
        if indeg[v] == 0:
            queue.append(v)
    best_cycle = 0
    pairs = 0
    for i in range(n):
        if removed[i]:
            continue
        length = 0
        j = i
        while not removed[j]:
            removed[j] = True
            length += 1
            j = favorite[j]
        if length == 2:
            pairs += depth[i] + depth[favorite[i]]
        else:
            best_cycle = max(best_cycle, length)
    return max(best_cycle, pairs)
